//! Cross-language parity for the large demo config (`samples/`, generated by
//! `samples/generate.py`): every language's file parses to exactly the JSON
//! file's value, validates against the demo `schema.json` with no
//! diagnostics, and the hot editor paths stay fast on a document this size.

use super::super::completion::{completions, key_hover};
use super::super::diagnostics::{build_schema, validate};
use super::Language;
use serde_json::Value;
use std::time::{Duration, Instant};

const SCHEMA: &str = include_str!("../../../../../schema.json");
const SAMPLES: [(Language, &str); 5] = [
    (
        Language::Json,
        include_str!("../../../../../samples/burrow.large.json"),
    ),
    (
        Language::Yaml,
        include_str!("../../../../../samples/burrow.large.yaml"),
    ),
    (
        Language::Toml,
        include_str!("../../../../../samples/burrow.large.toml"),
    ),
    (
        Language::Hcl,
        include_str!("../../../../../samples/burrow.large.hcl"),
    ),
    (
        Language::Xml,
        include_str!("../../../../../samples/burrow.large.xml"),
    ),
];

fn parsed(language: Language, source: &str) -> Value {
    match language.behavior().parse(source) {
        Ok(value) => value,
        Err(error) => panic!(
            "{language:?} sample does not parse at line {:?}: {}",
            error.line, error.message
        ),
    }
}

#[test]
fn every_language_sample_parses_to_the_same_document() {
    let expected = parsed(Language::Json, SAMPLES[0].1);
    for (language, source) in SAMPLES {
        assert!(
            source.lines().count() > 1500,
            "{language:?} sample should be a long document"
        );
        let document = parsed(language, source);
        if document != expected {
            let object = document.as_object().expect("an object");
            for (key, value) in expected.as_object().expect("an object") {
                assert_eq!(
                    object.get(key),
                    Some(value),
                    "{language:?} differs at /{key}"
                );
            }
            panic!("{language:?} has extra top-level keys");
        }
    }
}

#[test]
fn every_language_sample_validates_against_the_demo_schema() {
    let schema = build_schema(SCHEMA).expect("demo schema");
    for (language, source) in SAMPLES {
        let diagnostics = validate(source, Some(&schema), None, true, language.behavior());
        let messages: Vec<String> = diagnostics
            .iter()
            .map(|diagnostic| format!("{:?}: {}", diagnostic.line, diagnostic.message))
            .collect();
        assert!(messages.is_empty(), "{language:?}: {messages:#?}");
    }
}

/// Generous budgets: they catch accidental quadratic behavior on a ~2000-line
/// document, not small regressions (debug tests run slower than the wasm
/// release build).
#[test]
fn hot_paths_stay_fast_on_a_large_document() {
    let schema = build_schema(SCHEMA).expect("demo schema");
    let budget = Duration::from_millis(1500);
    for (language, source) in SAMPLES {
        let behavior = language.behavior();
        let started = Instant::now();
        let diagnostics = validate(source, Some(&schema), None, true, behavior);
        let validate_time = started.elapsed();
        assert!(diagnostics.is_empty());

        // Completion and hover in the middle and at the end of the document.
        let middle = source[..source.len() / 2].encode_utf16().count();
        let end = source.encode_utf16().count();
        let started = Instant::now();
        for cursor in [middle, end] {
            let _ = completions(source, cursor, true, Some(&schema), true, behavior);
        }
        let completion_time = started.elapsed();
        let started = Instant::now();
        let line = source.lines().count() / 2;
        let _ = key_hover(source, line, 4, Some(&schema), behavior);
        let hover_time = started.elapsed();

        assert!(
            validate_time < budget,
            "{language:?} validate took {validate_time:?}"
        );
        assert!(
            completion_time < budget,
            "{language:?} completion took {completion_time:?}"
        );
        assert!(
            hover_time < budget,
            "{language:?} hover took {hover_time:?}"
        );
        println!(
            "{language:?}: validate {validate_time:?}, 2 completions {completion_time:?}, hover {hover_time:?}"
        );
    }
}
